toast('车辆台账已导出', {
  description: '共 1,248 条，文件保留 24 小时。',
  action: { label: '下载', onClick: download },
  duration: Infinity,
})

useMutation({
  mutationFn: (starred: boolean) => api.star(id, starred),
  onMutate: async (starred) => { const prev = queryClient.getQueryData(key); queryClient.setQueryData(key, (old) => ({ ...old, starred })); return { prev } },
  onError: (_e, _v, ctx) => queryClient.setQueryData(key, ctx?.prev),
  onSettled: () => queryClient.invalidateQueries({ queryKey: key }),
})

@media print {
  nav, .toolbar { display: none; }
  thead { display: table-header-group; }
  tr { break-inside: avoid; }
}

export function useVehicleList(params: VehicleQuery) {
  return useQuery({ queryKey: ['vehicles', params], queryFn: ({ signal }) => api.listVehicles(params, { signal }) })
}

window.addEventListener('message', (event) => {
  if (!TRUSTED_ORIGINS.includes(event.origin)) return
  const message = parseWidgetMessage(event.data)
})

let refreshing: Promise<void> | null = null
async function onUnauthorized() {
  refreshing ??= api.refresh().finally(() => { refreshing = null })
  await refreshing
}

const channel = new BroadcastChannel('auth')
channel.onmessage = (event) => { if (event.data === 'logout') clearSession() }
export function logout() { clearSession(); channel.postMessage('logout') }
